import{z as n,x as s,o as e,c as o,q as l,j as A,D as a,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"评测服务化","description":"","frontmatter":{"title":"评测服务化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mm-eval-serving.md","filePath":"llm/mm-eval-serving.md","lastUpdated":1791063341000}'),m={name:"llm/mm-eval-serving.md"};function d(h,E,p,C,D,F){const B=s("Mermaid");return e(),o("div",null,[E[2]||(E[2]=l('<h1 id="评测服务化" tabindex="-1">评测服务化 <a class="header-anchor" href="#评测服务化" aria-label="Permalink to &quot;评测服务化&quot;">​</a></h1><div class="epigraph"><p>多模态服务的评测数字若不写明缓存是冷是热、视觉预算给了多少，那不是指标，是心情。</p><footer>—— 据 Yue et al., MMMU, 2024；Lu et al., MathVista, 2024；Li et al., POPE, EMNLP 2023 与长上下文评测服务化口径整理</footer></div><p><a href="/llm/mm-edge-multimodal">上一课</a>把整套栈压进端侧配额；至此云与端部署形态都齐了，缺一把统一的尺。多模态评测要同时回答两个问题：答得对不对、跑得快不快省不省——而两者被同一组变量搅在一起：首 token 延迟取决于图像大小与缓存状态，质量分数取决于视觉 token 预算。长上下文侧已有<a href="/llm/lc-eval-serving">评测服务化</a>的先例，内核侧有<a href="/llm/ak-benchmark-methodology">基准方法论</a>，本课把两者合到多模态：钉变量、分指标、带预算跑质量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两套评测各有盲区。质量侧的 <a href="/llm/mmmu-mathvista">MMMU 与 MathVista</a>、<a href="/llm/vlm-hallucination">POPE</a> 式幻觉集测模型能力，脚本通常默认最大分辨率、空缓存、独占机器——拿它推线上性能，等于用理想实验室外推晚高峰。服务侧的压测只管吞吐与延迟，输入图像随手抓，不看尺寸分布与命中率，同一服务换个图像集就能「快」一倍。多模态的独特麻烦在于：<strong>图像本身就是自变量</strong>，既进质量账又进成本账，不报告图像口径的数字无法跨实验比较。</p><p><span class="marginnote">术语翻译：冷缓存指服务第一次见这张图，要从头跑编码器，慢；热缓存指这张图的编码结果已经存过，直接查表复用，快。类比餐厅：冷缓存是「现点现做」，热缓存是「预制菜加热」。测量时必须说明你吃的是哪种——拿预制菜的上菜速度宣传堂食体验，就是后文说的「数字虚高最大单一来源」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议的核心是四个「钉」。<strong>钉输入</strong>：固定图像集并归档字节 hash，文本模板随版本记录。<strong>钉预处理</strong>：图像库版本、缩放插值、档位表写进评测配置，这些正是<a href="/llm/mm-serving-vision-encoder">嵌入缓存</a>键的内容，键变则一切旧数字作废。<strong>钉缓存状态</strong>：冷缓存（全部首次编码）、热缓存（嵌入与 KV 全命中）分开测、分开报，预热轮次显式声明。<strong>钉预算</strong>：视觉 token 上限是评测变量，写进每一行结果。</p><p>指标按流水段分层：编码器层每秒图数、prefill 层每秒视觉 token、请求层 TTFT 与 TPOT、成本层每图与每分钟视频的价格。分层让瓶颈可定位：请求层慢时先看哪一层饱和，再决定补卡还是改档位表。质量评测同样带变量跑：同一基准在三档<a href="/llm/mm-visual-token-budget">视觉预算</a>下各跑一遍，报告的是预算-精度曲线，不是单点分数；幻觉类题目在低预算档单独看，预算压得越低，语言先验补图越多，<a href="/llm/vlm-hallucination">物体幻觉</a>率是预算曲线里最先翘头的那条。</p><p><span class="marginnote">同一服务冷缓存的 TTFT 可达热缓存的数倍：热路径里编码与视觉 prefill 全部短路。「预热后测吞吐再外推线上首请求」，是自测数字虚高的最大单一来源。</span></p>',10)),(e(),A(i,null,{default:a(()=>[r(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E8%AF%84%E6%B5%8B%E8%AE%A1%E5%88%92%22%5D%20--%3E%20PIN%5B%22%E5%9B%9B%E9%92%89%EF%BC%9A%E8%BE%93%E5%85%A5%2F%E9%A2%84%E5%A4%84%E7%90%86%2F%E7%BC%93%E5%AD%98%2F%E9%A2%84%E7%AE%97%22%5D%0A%20%20PIN%20--%3E%20MICRO%5B%22%E5%88%86%E5%B1%82%E5%BE%AE%E5%9F%BA%E5%87%86%EF%BC%9A%E7%BC%96%E7%A0%81%E4%B8%8E%20prefill%22%5D%0A%20%20MICRO%20--%3E%20E2E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E5%8D%8F%E8%AE%AE%EF%BC%9A%E5%86%B7%E7%83%AD%E5%88%86%E5%BC%80%E6%B5%8B%22%5D%0A%20%20E2E%20--%3E%20QUAL%5B%22%E8%B4%A8%E9%87%8F%E5%9F%BA%E5%87%86%E6%8C%89%E4%B8%89%E6%A1%A3%E9%A2%84%E7%AE%97%E6%89%AB%E6%8F%8F%22%5D%0A%20%20QUAL%20--%3E%20HALL%5B%22%E4%BD%8E%E9%A2%84%E7%AE%97%E6%A1%A3%E5%8D%95%E7%9C%8B%E5%B9%BB%E8%A7%89%E9%A2%98%22%5D%0A%20%20HALL%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E5%88%86%E5%B1%82%E6%8C%87%E6%A0%87%E5%8A%A0%E9%A2%84%E7%AE%97-%E7%B2%BE%E5%BA%A6%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四钉里最易被忽视的是预处理钉，因为它失效得最安静：图像库升级换了插值，所有图像的像素分布微变，嵌入缓存键没变、旧数字被拿去和新模型比，结论看起来是「模型没进步」。这是<a href="/llm/mm-serving-vision-encoder">缓存键版本纪律</a>的评测版——评测配置是缓存键的镜像，评测系统应直接消费线上键的定义，而不是各写一份。统计口径按<a href="/llm/eval-variance-seed">评测方差</a>钉死：跑几轮、取什么分位；多模态单轮成本高，图省钱跑一轮，方差就把结论吃掉。</p><p><span class="marginnote">「图省钱跑一轮」为什么危险：假设某基准单轮分数的随机波动约 ±1.5 分，两个模型各跑一轮得到 71.2 与 72.8，看起来差 1.6 分——其实完全可能没有真实差距。多跑三五轮取均值与区间，才能分清「真差距」和「抖动」。类比称金子：精度 ±0.5 克的秤上，两次称重差 0.3 克说明不了轻重。</span></p><p>预算-精度曲线的机制在<a href="/llm/mm-visual-token-budget">预算课</a>已给：削减先伤高信息密度区。评测的价值是把曲线从论断变成每个模型的实测——同一档预算，OCR 型任务掉得早、描述型几乎平，曲线形状本身就是选型依据。服务与质量评测共用图像集还有一层红利：同一条请求既能算对错又能算成本，质量-成本散点图直接可画，为下一课的容量与定价备料。</p>',4)),(e(),A(i,null,{default:a(()=>[r(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E5%9B%BE%E5%83%8F%E5%BA%93%E5%8D%87%E7%BA%A7%EF%BC%9A%E6%8D%A2%E4%BA%86%E7%BC%A9%E6%94%BE%E6%8F%92%E5%80%BC%22%5D%20--%3E%20PIX%5B%22%E6%89%80%E6%9C%89%E5%9B%BE%E5%83%8F%E7%B4%A0%E5%88%86%E5%B8%83%E5%BE%AE%E5%8F%98%22%5D%0A%20%20PIX%20--%3E%20KEY%7B%22%E5%B5%8C%E5%85%A5%E7%BC%93%E5%AD%98%E9%94%AE%E6%9B%B4%E6%96%B0%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20KEY%20--%3E%7C%22%E6%B2%A1%E6%9B%B4%E6%96%B0%EF%BC%88%E5%A4%B1%E6%95%88%E6%9C%80%E5%AE%89%E9%9D%99%EF%BC%89%22%7C%20OLD%5B%22%E7%BB%A7%E7%BB%AD%E5%91%BD%E4%B8%AD%E6%97%A7%E5%B5%8C%E5%85%A5%22%5D%0A%20%20KEY%20--%3E%7C%22%E6%9B%B4%E6%96%B0%E5%B9%B6%E5%BD%92%E6%A1%A3%22%7C%20NEW%5B%22%E9%87%8D%E6%96%B0%E7%BC%96%E7%A0%81%EF%BC%8C%E6%96%B0%E6%97%A7%E6%95%B0%E5%AD%97%E5%8F%AF%E5%BD%92%E5%9B%A0%22%5D%0A%20%20OLD%20--%3E%20CMP%5B%22%E6%8B%BF%E6%97%A7%E6%95%B0%E5%AD%97%E6%AF%94%E6%96%B0%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20CMP%20--%3E%20WRONG%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9A%E6%A8%A1%E5%9E%8B%E6%B2%A1%E8%BF%9B%E6%AD%A5%EF%BC%88%E5%AE%9E%E4%B8%BA%E5%8F%A3%E5%BE%84%E6%BC%82%E7%A7%BB%EF%BC%89%22%5D%0A%20%20NEW%20--%3E%20OK%5B%22%E6%9B%B2%E7%BA%BF%E5%8F%AF%E4%BF%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<p><span class="marginnote">这张图回答的是：「预处理钉为什么最容易被忽视又最致命？」它的失效不报错、不崩程序，只是让所有对比悄悄失真。类比体重秤：你换了秤（新图像库）但没换刻度（缓存键没变），之后记录的「体重变化」全是假的——问题不在身体，在尺子。评测纪律的本质是先钉尺子，再谈测量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准侧的老问题在多模态上只会更重：公开集的污染与<a href="/llm/benchmark-saturation">饱和</a>让单点分数趋同，预算曲线与自有图像集是缓解，不是解药。线上与离线的差也不只是缓存：真实流量里图像分布高度偏斜——聊天里截图与头像占大头，基准里的文档页是小众，离线分数要配线上分布加权才有参考性。评测也有成本与合规：全量基准的钱不可忽略，敏感图像不能出测试环境。语音与视频各有时间维指标（端点延迟、事件定位），四钉框架照用，口径按模态补。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态评测必须双轨：质量与成本，两轨共享图像自变量，任何一行都要报口径。</li><li>四钉协议：输入 hash、预处理版本、冷热缓存、视觉预算，缺一即不可比。</li><li>指标按流水段分层：编码、prefill、请求、成本，瓶颈定位靠分层饱和度。</li><li>质量跑预算-精度曲线，幻觉率在低预算档最先翘头，是选型依据。</li><li>线上分布偏斜与基准污染靠加权与自建集缓解；评测配置直接消费线上缓存键。</li><li>出处：据 MMMU（Yue et al., 2024）、MathVista（Lu et al., 2024）、POPE（Li et al., EMNLP 2023）与评测方法论课程口径整理。</li></ul>',5))])}const u=n(m,[["render",d]]);export{f as __pageData,u as default};
